var params = $input.first().json;

if (!params.template_ref) {
  throw new Error('Missing required field: template_ref. Specify which template to generate data for.');
}
if (!params.user_id) {
  throw new Error('Missing required field: user_id');
}

var uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidPattern.test(params.user_id)) {
  throw new Error('Invalid user_id format: "' + params.user_id + '". Expected UUID.');
}

var supabaseUrl = params.SUPABASE_URL || 'https://egrzvwnjrtpwwmqzimff.supabase.co';
var bucket = params.SUPABASE_BUCKET || 'panicleDevelop_1';
var downloadUrl = supabaseUrl + '/storage/v1/object/' + bucket + '/PDF-templates/' + params.template_ref + '/Generate_Data.xlsx';

return [{
  json: {
    template_ref: params.template_ref,
    user_id: params.user_id,
    run_id: params.run_id,
    SUPABASE_URL: supabaseUrl,
    SUPABASE_BUCKET: bucket,
    download_url: downloadUrl
  }
}];

var item = $input.first();
var config = $('Validate Params').first().json;

var hasBinary = false;
if (item.binary) {
  var keys = Object.keys(item.binary);
  if (keys.length > 0) { hasBinary = true; }
}

if (!hasBinary) {
  throw new Error('Generate_Data.xlsx not found in Supabase storage. Expected path: PDF-templates/' + config.template_ref + '/Generate_Data.xlsx. Upload the edited gap analysis Excel as Generate_Data.xlsx first.');
}

return [{
  json: {
    template_ref: config.template_ref,
    user_id: config.user_id,
    run_id: config.run_id,
    SUPABASE_URL: config.SUPABASE_URL,
    SUPABASE_BUCKET: config.SUPABASE_BUCKET
  },
  binary: item.binary
}];

var rows = $input.all();
var config = $('Check Download Result').first().json;
var templateRef = config.template_ref;

var SYNTHETIC_DATA = {
  'first_name': 'Sarah',
  'last_name': 'Mitchell',
  'email': 'sarah.mitchell@greenfield-energy.co.uk',
  'phone_number': '+44 20 7946 0958',
  'mobile_number': '+44 7700 900456',
  'company_name': 'Greenfield Energy Systems Ltd',
  'company_number': '09876543',
  'company_address': 'Unit 7, Innovation Park, Cambridge, CB1 2QA',
  'postcode': 'CB1 2QA',
  'title': 'Dr',
  'position': 'Principal Process Engineer',
  'website': 'www.greenfield-energy.co.uk',
  'address': '42 Riverside Walk, Cambridge, CB5 8HT',
  'city': 'Cambridge',
  'county': 'Cambridgeshire',
  'country': 'United Kingdom',
  'date_of_birth': '1985-03-15',
  'national_insurance': 'AB123456C',
  'vat_number': 'GB123456789',
  'bank_sort_code': '30-90-28',
  'bank_account': '12345678'
};

function isTrueFlag(val) {
  if (val === true || val === 1) { return true; }
  if (typeof val === 'string') {
    var lower = val.toLowerCase().trim();
    if (lower === 'true' || lower === 'yes' || lower === '1') { return true; }
  }
  return false;
}

var colCreateData = '';
var colCreated = '';
var colRemoveLink = '';
var colSuggestedKey = '';
var colSuggestedSource = '';
var colPdfField = '';
var colTemplateRef = '';
var colFieldType = '';
var colCurrentStatus = '';
var colCurrentMapping = '';

var allKeysSeen = {};
for (var ri = 0; ri < rows.length; ri++) {
  var rkeys = Object.keys(rows[ri].json);
  for (var rki = 0; rki < rkeys.length; rki++) {
    allKeysSeen[rkeys[rki]] = true;
  }
}
var keys = Object.keys(allKeysSeen);
for (var k = 0; k < keys.length; k++) {
  var lk = keys[k].toLowerCase();
  if (lk.indexOf('create') >= 0 && lk.indexOf('data') >= 0) { colCreateData = keys[k]; }
  else if (lk === 'created') { colCreated = keys[k]; }
  else if (lk.indexOf('remove') >= 0 && lk.indexOf('link') >= 0) { colRemoveLink = keys[k]; }
  else if (lk.indexOf('suggested') >= 0 && lk.indexOf('key') >= 0) { colSuggestedKey = keys[k]; }
  else if (lk.indexOf('suggested') >= 0 && lk.indexOf('source') >= 0) { colSuggestedSource = keys[k]; }
  else if (lk.indexOf('pdf') >= 0 && lk.indexOf('field') >= 0 && lk.indexOf('name') >= 0) { colPdfField = keys[k]; }
  else if (lk.indexOf('template') >= 0 && lk.indexOf('ref') >= 0) { colTemplateRef = keys[k]; }
  else if (lk.indexOf('field') >= 0 && lk.indexOf('type') >= 0) { colFieldType = keys[k]; }
  else if (lk.indexOf('current') >= 0 && lk.indexOf('status') >= 0) { colCurrentStatus = keys[k]; }
  else if (lk.indexOf('current') >= 0 && lk.indexOf('mapping') >= 0) { colCurrentMapping = keys[k]; }
}

if (!colCreateData) {
  throw new Error('Column "Create Data" not found in Excel. Keys found across all rows: ' + keys.join(', '));
}
if (!colPdfField) {
  throw new Error('Column "PDF Field Name" not found in Excel.');
}
if (!colCreated) { colCreated = 'Created'; }
if (!colRemoveLink) { colRemoveLink = 'Remove Link'; }

var fieldsToUpdate = [];
var fieldsToRemove = [];
var syntheticValues = {};
var skipped = [];
var updatedExcelRows = [];
var debugBlankCount = 0;
var debugHasCreateDataKey = 0;

for (var i = 0; i < rows.length; i++) {
  var row = rows[i].json;
  var pdfField = colPdfField ? String(row[colPdfField] || '').trim() : '';
  var suggestedKey = colSuggestedKey ? String(row[colSuggestedKey] || '').trim() : '';
  var suggestedSource = colSuggestedSource ? String(row[colSuggestedSource] || '').trim() : '';
  var rowTplRef = colTemplateRef ? String(row[colTemplateRef] || '').trim() : '';
  var removeFlag = colRemoveLink ? isTrueFlag(row[colRemoveLink]) : false;
  var hasCreateDataKey = row.hasOwnProperty(colCreateData);
  var rawCreateData = hasCreateDataKey ? row[colCreateData] : undefined;
  var createDataStr = String(rawCreateData === undefined || rawCreateData === null ? '' : rawCreateData).trim();
  var isBlank = !hasCreateDataKey || createDataStr === '' || createDataStr === '.';
  var isTrue = isTrueFlag(rawCreateData);
  var isLiteralValue = !isBlank && !isTrue;

  if (hasCreateDataKey) { debugHasCreateDataKey++; }

  var excelRow = {};
  var rowKeys = Object.keys(row);
  for (var rk = 0; rk < rowKeys.length; rk++) {
    excelRow[rowKeys[rk]] = row[rowKeys[rk]];
  }
  if (!excelRow.hasOwnProperty(colCreated)) { excelRow[colCreated] = ''; }
  if (!excelRow.hasOwnProperty(colRemoveLink)) { excelRow[colRemoveLink] = ''; }

  if (removeFlag && pdfField) {
    if (rowTplRef && rowTplRef !== templateRef) {
      skipped.push(pdfField + ' (remove link: different template ' + rowTplRef + ')');
    } else {
      fieldsToRemove.push(pdfField);
    }
    updatedExcelRows.push(excelRow);
    continue;
  }

  if (isBlank) {
    debugBlankCount++;
    updatedExcelRows.push(excelRow);
    continue;
  }

  if (!pdfField) {
    skipped.push('Row ' + (i + 2) + ': empty PDF field name');
    updatedExcelRows.push(excelRow);
    continue;
  }

  if (rowTplRef && rowTplRef !== templateRef) {
    skipped.push(pdfField + ' (different template: ' + rowTplRef + ')');
    updatedExcelRows.push(excelRow);
    continue;
  }

  if (suggestedSource && suggestedSource !== 'users' && suggestedSource !== 'user_details') {
    skipped.push(pdfField + ' (source: ' + suggestedSource + ' -- not user data, skipped)');
    updatedExcelRows.push(excelRow);
    continue;
  }

  var effectiveKey = suggestedKey;
  if (!effectiveKey) {
    effectiveKey = pdfField.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  }
  var effectiveSource = suggestedSource || 'user_details';

  var value;
  if (isLiteralValue) {
    value = createDataStr;
  } else {
    value = SYNTHETIC_DATA[effectiveKey];
    if (!value) {
      value = 'Synthetic ' + effectiveKey.replace(/_/g, ' ');
    }
  }

  fieldsToUpdate.push({
    pdfField: pdfField,
    dataKey: effectiveKey,
    source: effectiveSource
  });
  syntheticValues[effectiveKey] = value;

  if (colCreated) { excelRow[colCreated] = 'TRUE'; }
  updatedExcelRows.push(excelRow);
}

if (fieldsToUpdate.length === 0 && fieldsToRemove.length === 0) {
  var debugCols = 'Detected columns: CreateData=' + colCreateData + ', Created=' + colCreated + ', RemoveLink=' + colRemoveLink + ', SuggestedKey=' + colSuggestedKey + ', PdfField=' + colPdfField;
  var debugStats = ' Total rows: ' + rows.length + ', Blank/no-CreateData: ' + debugBlankCount + ', Rows with CreateData key: ' + debugHasCreateDataKey;
  var debugDataRow = '';
  for (var dr = 0; dr < rows.length; dr++) {
    var drKeys = Object.keys(rows[dr].json);
    if (drKeys.indexOf(colCreateData) >= 0) {
      var drRow = rows[dr].json;
      debugDataRow = ' Row' + dr + ' has CreateData key: val=' + JSON.stringify(drRow[colCreateData]) + ' (type:' + typeof drRow[colCreateData] + ')';
      break;
    }
  }
  if (!debugDataRow) { debugDataRow = ' No row has the "' + colCreateData + '" key as own property.'; }
  var debugSkipped = skipped.length > 0 ? ' Skipped(' + skipped.length + '): ' + skipped.slice(0, 5).join('; ') : '';
  var debugAllKeys = ' All keys seen: ' + keys.join(', ');
  throw new Error('No actionable rows found.' + debugCols + '.' + debugStats + '.' + debugDataRow + '.' + debugSkipped + debugAllKeys);
}

return [{
  json: {
    template_ref: templateRef,
    user_id: config.user_id,
    run_id: config.run_id,
    SUPABASE_URL: config.SUPABASE_URL,
    SUPABASE_BUCKET: config.SUPABASE_BUCKET,
    fields_to_update: fieldsToUpdate,
    fields_to_remove: fieldsToRemove,
    synthetic_values: syntheticValues,
    synthetic_count: Object.keys(syntheticValues).length,
    fields_count: fieldsToUpdate.length,
    remove_count: fieldsToRemove.length,
    skipped: skipped,
    updated_excel_rows: updatedExcelRows,
    _columns_detected: {
      createData: colCreateData,
      created: colCreated,
      removeLink: colRemoveLink,
      suggestedKey: colSuggestedKey,
      suggestedSource: colSuggestedSource,
      pdfField: colPdfField,
      templateRef: colTemplateRef
    }
  }
}];

var synthData = $('Filter & Generate Synthetic Data').first().json;
var fetchResult = $input.all();

var existing = null;
if (fetchResult.length > 0) {
  existing = fetchResult[0].json;
}
if (Array.isArray(existing)) {
  existing = existing[0];
}

if (!existing || !existing.id) {
  throw new Error('Template not found: ' + synthData.template_ref + '. Check that the template_ref exists in pdf_ff_templates.');
}

var oldMapping = existing.source_to_template_mapping || [];
var fieldsToUpdate = synthData.fields_to_update;
var fieldsToRemove = synthData.fields_to_remove || [];

var updateLookup = {};
for (var f = 0; f < fieldsToUpdate.length; f++) {
  updateLookup[fieldsToUpdate[f].pdfField] = {
    dataKey: fieldsToUpdate[f].dataKey,
    source: fieldsToUpdate[f].source
  };
}

var removeLookup = {};
for (var r = 0; r < fieldsToRemove.length; r++) {
  removeLookup[fieldsToRemove[r]] = true;
}

var newMapping = [];
var updatedCount = 0;
var removedCount = 0;
for (var m = 0; m < oldMapping.length; m++) {
  var entry = oldMapping[m];
  if (removeLookup[entry.pdfField]) {
    newMapping.push({
      pdfField: entry.pdfField,
      fieldType: entry.fieldType || '',
      dataKey: '',
      source: '',
      confidence: '',
      score: 0,
      notes: 'Mapping removed ' + synthData.run_id
    });
    removedCount++;
  } else if (updateLookup[entry.pdfField]) {
    var update = updateLookup[entry.pdfField];
    newMapping.push({
      pdfField: entry.pdfField,
      fieldType: entry.fieldType || '',
      dataKey: update.dataKey,
      source: update.source,
      confidence: 'synthetic',
      score: 1.0,
      notes: 'Synthetic data generated ' + synthData.run_id
    });
    updatedCount++;
  } else {
    newMapping.push(entry);
  }
}

return [{
  json: {
    template_ref: synthData.template_ref,
    user_id: synthData.user_id,
    run_id: synthData.run_id,
    SUPABASE_URL: synthData.SUPABASE_URL,
    SUPABASE_BUCKET: synthData.SUPABASE_BUCKET,
    new_mapping: newMapping,
    details_jsonb: synthData.synthetic_values,
    updated_field_count: updatedCount,
    removed_field_count: removedCount,
    total_mapping_count: newMapping.length,
    synthetic_keys: Object.keys(synthData.synthetic_values),
    skipped: synthData.skipped,
    updated_excel_rows: synthData.updated_excel_rows
  }
}];

var payload = $('Build Update Payload').first().json;
var excelRows = payload.updated_excel_rows || [];
var result = [];
for (var i = 0; i < excelRows.length; i++) {
  result.push({ json: excelRows[i] });
}
if (result.length === 0) {
  result.push({ json: { 'Note': 'No rows to write' } });
}
return result;

var payload = $('Build Update Payload').first().json;
var patchResult = $('Update Template Record').first().json;
var rpcResult = $('Upsert User Details').first().json;

var syntheticKeys = payload.synthetic_keys;
var keysStr = syntheticKeys.length > 0 ? syntheticKeys.join(', ') : '(none)';

var msg = 'Synthetic data generation complete for template ' + payload.template_ref + '.';
if (payload.updated_field_count > 0) {
  msg = msg + ' ' + payload.updated_field_count + ' field mapping(s) created (confidence: synthetic).';
  msg = msg + ' ' + syntheticKeys.length + ' synthetic data key(s): ' + keysStr + '.';
  msg = msg + ' User details upserted for user ' + payload.user_id + '.';
}
if (payload.removed_field_count > 0) {
  msg = msg + ' ' + payload.removed_field_count + ' field mapping(s) removed (unlinked).';
}
if (payload.skipped.length > 0) {
  msg = msg + ' ' + payload.skipped.length + ' row(s) skipped.';
}
msg = msg + ' Generate_Data.xlsx updated with Created=TRUE markers.';

return [{
  json: {
    status: 'success',
    message: msg,
    run_id: payload.run_id,
    template_ref: payload.template_ref,
    user_id: payload.user_id,
    fields_created: payload.updated_field_count,
    fields_removed: payload.removed_field_count,
    total_mapping_fields: payload.total_mapping_count,
    synthetic_data_keys: syntheticKeys,
    synthetic_values: payload.details_jsonb,
    skipped_rows: payload.skipped,
    next_step: 'Run Fill Form workflow with template_ref="' + payload.template_ref + '" and user_id="' + payload.user_id + '" to test the synthetic data.'
  }
}];
